mapper.select:
SELECT m.device_name as deviceName, m.device_code as deviceCode, m.channel_name as channelName, m.channel_code as channelCode, d.device_status as deviceStatus, m.province_name as provinceName, m.city_name as cityName, m.county_name as countyName FROM vm_checkpoint_device_info_t m, vm_device_info_t d, ( SELECT a.device_code, a.accept_node FROM vm_order_devices a WHERE a.delete_flag = 0 AND a.ord_status in(0, 1, 2) and a.tenant_id = #{tenantId} and a.industry_code = #{industryCode} GROUP BY a.device_code) t WHERE t.device_code = d.device_code AND m.device_code = d.device_code AND m.delete_flag = 0 AND d.delete_flag = '0' ${dataScope}
AND m.cp_id in
#{item}
AND m.province_id = #{provinceId}
AND m.city_id = #{cityId}
AND m.county_id = #{countyId}
AND m.device_code like CONCAT('%', #{deviceCode}, '%')
AND d.device_status = #{deviceStatus}
AND m.channel_code like CONCAT('%', #{channelCode}, '%')
AND m.channel_name like CONCAT('%', #{channelName}, '%')
AND m.device_name like CONCAT('%', #{deviceName}, '%')
order by m.province_id, m.city_id, m.county_id, m.device_code
